 require(newKittenId == uint256(uint32(newKittenId)));
 Birth(
 _owner,
 newKittenId,
 uint256(_monster.matronId),
 uint256(_monster.sireId),
 _monster.genes,
 uint16(_generation)
 );
 _transfer(0, _owner, newKittenId);
 return newKittenId;
 }

